"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { useState } from "react";
import { authClient } from "@/lib/auth-client";

type Mode = "sign-in" | "sign-up";

const inputClass =
  "w-full rounded border border-black/15 bg-transparent px-3 py-2 text-sm dark:border-white/20";
const buttonClass =
  "w-full rounded bg-foreground px-3 py-2 text-sm font-medium text-background disabled:opacity-50";

export function AuthForm({ mode, googleEnabled }: { mode: Mode; googleEnabled: boolean }) {
  const router = useRouter();
  const [error, setError] = useState<string | null>(null);
  const [pending, setPending] = useState(false);

  async function onSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setError(null);
    setPending(true);
    const form = new FormData(e.currentTarget);
    const email = String(form.get("email"));
    const password = String(form.get("password"));

    const { error } =
      mode === "sign-up"
        ? await authClient.signUp.email({ name: String(form.get("name")), email, password })
        : await authClient.signIn.email({ email, password });

    if (error) {
      setError(error.message ?? "Something went wrong");
      setPending(false);
      return;
    }
    router.push("/dashboard");
    router.refresh();
  }

  async function onGoogle() {
    setError(null);
    setPending(true);
    const { error } = await authClient.signIn.social({
      provider: "google",
      callbackURL: "/dashboard",
      errorCallbackURL: "/sign-in",
    });
    if (error) {
      setError(error.message ?? "Google sign-in failed");
      setPending(false);
    }
  }

  const isSignUp = mode === "sign-up";

  return (
    <main className="mx-auto w-full max-w-sm p-8">
      <h1 className="text-2xl font-semibold">{isSignUp ? "Create your account" : "Sign in"}</h1>

      <form onSubmit={onSubmit} className="mt-6 space-y-3">
        {isSignUp && (
          <input name="name" required placeholder="Name" autoComplete="name" className={inputClass} />
        )}
        <input
          name="email"
          type="email"
          required
          placeholder="Email"
          autoComplete="email"
          className={inputClass}
        />
        <input
          name="password"
          type="password"
          required
          minLength={8}
          placeholder="Password"
          autoComplete={isSignUp ? "new-password" : "current-password"}
          className={inputClass}
        />
        <button type="submit" disabled={pending} className={buttonClass}>
          {isSignUp ? "Sign up" : "Sign in"}
        </button>
      </form>

      {googleEnabled && (
        <button
          type="button"
          onClick={onGoogle}
          disabled={pending}
          className="mt-3 w-full rounded border border-black/15 px-3 py-2 text-sm font-medium disabled:opacity-50 dark:border-white/20"
        >
          Continue with Google
        </button>
      )}

      {error && <p className="mt-4 text-sm text-red-600">{error}</p>}

      <p className="mt-6 text-sm opacity-70">
        {isSignUp ? (
          <>
            Already have an account? <Link href="/sign-in" className="underline">Sign in</Link>
          </>
        ) : (
          <>
            New to Notely? <Link href="/sign-up" className="underline">Create an account</Link>
          </>
        )}
      </p>
    </main>
  );
}
EOF
